}
animate();

const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xffffff, 1.35);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xbfd7ff, 0.55);
fillLight.position.set(-7, 4, 5);

const rimLight = new THREE.PointLight(0xaad6ff, 0.45, 22);
rimLight.position.set(-4, 3, -5);

const accentLight = new THREE.PointLight(0xffd700, 0.3, 15);
accentLight.position.set(0, 4, 0);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.32), keyLight, fillLight, rimLight, accentLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(12, 128),
  new THREE.MeshStandardMaterial({ 
    color: 0xe6ecf5, 
    roughness: 0.85, 
    metalness: 0.05 
  })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -2;
floor.receiveShadow = true;
scene.add(floor);

const commGroup = new THREE.Group();
scene.add(commGroup);

const nodeMaterial = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  metalness: 0.1,
  roughness: 0.2,
  transmission: 0.6,
  thickness: 1.5,
  clearcoat: 1,
  clearcoatRoughness: 0.1,
  ior: 1.5
});

const coreMaterial = new THREE.MeshStandardMaterial({
  color: 0x2d3a4f,
  roughness: 0.4,
  metalness: 0.8
});

const activeMaterial = new THREE.MeshStandardMaterial({
  color: 0x00d4ff,
  emissive: 0x00d4ff,
  emissiveIntensity: 0.8,
  roughness: 0.2,
  metalness: 0.1
});

const ackMaterial = new THREE.MeshStandardMaterial({
  color: 0xff6b35,
  emissive: 0xff6b35,
  emissiveIntensity: 0.6,
  roughness: 0.2,
  metalness: 0.1
});

const nodeA = new THREE.Group();
const nodeAGeometry = new THREE.IcosahedronGeometry(0.8, 2);
const nodeAMesh = new THREE.Mesh(nodeAGeometry, nodeMaterial);
nodeAMesh.castShadow = true;
nodeAMesh.receiveShadow = true;
const nodeACore = new THREE.Mesh(new THREE.IcosahedronGeometry(0.4, 0), coreMaterial);
nodeA.add(nodeAMesh, nodeACore);
nodeA.position.set(-3, 0.5, 0);
commGroup.add(nodeA);

const nodeB = new THREE.Group();
const nodeBMesh = new THREE.Mesh(nodeAGeometry, nodeMaterial);
nodeBMesh.castShadow = true;
nodeBMesh.receiveShadow = true;
const nodeBCore = new THREE.Mesh(new THREE.IcosahedronGeometry(0.4, 0), coreMaterial);
nodeB.add(nodeBMesh, nodeBCore);
nodeB.position.set(3, 0.5, 0);
commGroup.add(nodeB);

const packetGeometry = new THREE.SphereGeometry(0.12, 16, 16);
const packets = [];
for (let i = 0; i < 8; i++) {
  const packet = new THREE.Mesh(packetGeometry, activeMaterial);
  packet.castShadow = true;
  commGroup.add(packet);
  packets.push({ mesh: packet, offset: i * 0.8, speed: 2.5, direction: 1 });
}

const ackPacketGeometry = new THREE.SphereGeometry(0.1, 16, 16);
const ackPackets = [];
for (let i = 0; i < 6; i++) {
  const packet = new THREE.Mesh(ackPacketGeometry, ackMaterial);
  packet.castShadow = true;
  commGroup.add(packet);
  ackPackets.push({ mesh: packet, offset: i * 0.6 + 0.3, speed: 3, direction: -1 });
}

const ringGeometry = new THREE.TorusGeometry(1.2, 0.02, 16, 100);
const ringMaterial = new THREE.MeshBasicMaterial({ 
  color: 0xaad6ff, 
  transparent: true, 
  opacity: 0.3 
});
const ringA = new THREE.Mesh(ringGeometry, ringMaterial);
ringA.rotation.x = Math.PI / 2;
ringA.position.copy(nodeA.position);
commGroup.add(ringA);

const ringB = new THREE.Mesh(ringGeometry, ringMaterial.clone());
ringB.rotation.x = Math.PI / 2;
ringB.position.copy(nodeB.position);
commGroup.add(ringB);

const turnIndicator = new THREE.Group();
for (let i = 0; i < 3; i++) {
  const indicator = new THREE.Mesh(
    new THREE.CylinderGeometry(0.05, 0.05, 0.4, 8),
    i === 2 ? activeMaterial : new THREE.MeshStandardMaterial({ 
      color: 0xc0c9d6, 
      roughness: 0.5,
      metalness: 0.3 
    })
  );
  indicator.position.x = (i - 1) * 0.3;
  indicator.position.y = 2.2;
  turnIndicator.add(indicator);
}
commGroup.add(turnIndicator);

const connectionLine = new THREE.Mesh(
  new THREE.CylinderGeometry(0.01, 0.01, 6, 8),
  new THREE.MeshBasicMaterial({ 
    color: 0xcdd6e4, 
    transparent: true, 
    opacity: 0.4 
  })
);
connectionLine.rotation.z = Math.PI / 2;
connectionLine.position.y = 0.5;
commGroup.add(connectionLine);

camera.position.set(0, 3.5, 8);
camera.lookAt(0, 0.5, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  nodeA.rotation.y = t * 0.5;
  nodeA.rotation.z = Math.sin(t * 0.3) * 0.1;
  nodeA.position.y = 0.5 + Math.sin(t * 0.8) * 0.05;

  nodeB.rotation.y = -t * 0.5;
  nodeB.rotation.z = Math.cos(t * 0.3) * 0.1;
  nodeB.position.y = 0.5 + Math.cos(t * 0.8) * 0.05;

  ringA.position.copy(nodeA.position);
  ringA.scale.setScalar(1 + Math.sin(t * 2) * 0.05);
  ringA.material.opacity = 0.2 + Math.sin(t * 3) * 0.1;

  ringB.position.copy(nodeB.position);
  ringB.scale.setScalar(1 + Math.cos(t * 2) * 0.05);
  ringB.material.opacity = 0.2 + Math.cos(t * 3) * 0.1;

  packets.forEach((p, i) => {
    const progress = (t * p.speed + p.offset) % 2;
    const x = -3 + progress * 3;
    p.mesh.position.set(x, 0.5 + Math.sin(progress * Math.PI) * 0.3, 0);
    p.mesh.scale.setScalar(1 + Math.sin(progress * Math.PI) * 0.5);
    p.mesh.material.emissiveIntensity = 0.4 + Math.sin(progress * Math.PI) * 0.8;
  });

  ackPackets.forEach((p, i) => {
    const progress = (t * p.speed + p.offset) % 2;
    const x = 3 - progress * 3;
    p.mesh.position.set(x, 0.5 - Math.sin(progress * Math.PI) * 0.2, 0.2);
    p.mesh.scale.setScalar(1 + Math.sin(progress * Math.PI) * 0.3);
  });

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;
  accentLight.intensity = 0.3 + Math.sin(t * 4) * 0.15;

  turnIndicator.rotation.y = Math.sin(t * 0.5) * 0.1;

  renderer.render(scene, camera);
}
animate();

